import json,urllib.request,urllib.error,urllib.parse,hashlib,concurrent.futures,re,unicodedata
def fetch(url,cap):
 req=urllib.request.Request(url,headers={'User-Agent':'Telecom-PT public data catalog review','Accept':'application/json, text/plain, */*'})
 with urllib.request.urlopen(req,timeout=12) as res:
  b=res.read(cap+1)
  if len(b)>cap:raise ValueError('response exceeds audit cap')
  return b,res.status
def clean(s):return ''.join(c for c in unicodedata.normalize('NFKD',str(s).casefold()) if not unicodedata.combining(c))
def err(e):
 if isinstance(e,urllib.error.HTTPError):return {'status':e.code}
 return {'error':type(e).__name__,'detail':str(e)[:160]}
def catalog(q):
 r={'query':q}
 try:
  b,status=fetch('https://dados.gov.pt/api/1/datasets/?'+urllib.parse.urlencode({'q':q,'page_size':20}),3*1024*1024)
  j=json.loads(b);rows=j['data'];r.update(status=status,total=j.get('total'),examined=len(rows),more_pages=bool(j.get('next_page')))
  r['titles']=[str(x.get('title',''))[:150] for x in rows]
  r['potential_contract_metadata']=[str(x.get('title',''))[:150] for x in rows if re.search(r'fideliza|contrat',clean(x.get('title','')))]
  r['scope']='catalog metadata only; no dataset record content inspected'
 except Exception as e:r.update(err(e))
 return r
def gleif():
 r={'source':'GLEIF public legal entity API'}
 try:
  b,status=fetch('https://api.gleif.org/api/v1/lei-records?'+urllib.parse.urlencode({'filter[entity.legalAddress.country]':'PT','page[size]':1}),512*1024)
  j=json.loads(b);rows=j['data'];fields=sorted(rows[0]['attributes']['entity'].keys()) if rows else []
  r.update(status=status,total=j.get('meta',{}).get('pagination',{}).get('total'),entity_fields=fields,sample_count=len(rows),scope='schema only; no individual entity names or IDs retained')
  r['telecom_contract_field']=any(re.search(r'telecom|fideliza|contract|operator|carrier',x,re.I) for x in fields)
 except Exception as e:r.update(err(e))
 return r
def repo(it):
 owner,rev,path,blob=it;r={'repository':owner,'revision':rev,'path':path}
 try:
  b,status=fetch('https://raw.githubusercontent.com/'+owner+'/'+rev+'/'+path,65536)
  assert hashlib.sha1(b'blob '+str(len(b)).encode()+bytes([0])+b).hexdigest()==blob
  t=clean(b.decode('utf-8'));r.update(status=status,verified_git_blob=True)
  r['mentions']={k:bool(re.search(p,t)) for k,p in {'fidelity':r'fideliza|lock.in','public_procurement':r'public contracts|contratos publicos|procurement','synthetic_or_fictional':r'synthetic|fictional','user_supplied_imports':r'import|bring mapped exports','renewal':r'renewal|renovacao','invoice_due':r'date_due','contract_end_date':r'contract.end.date|fim da fidelizacao|end of commitment'}.items()}
 except Exception as e:r.update(err(e))
 return r
